#!/usr/bin/env python3
"""Database Migration Script v2.3.1

Handles schema migrations and data imports for the analytics pipeline.
Supports bulk CSV/SQL file uploads for seeding reference data during migrations.
"""

import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from werkzeug.utils import secure_filename
import subprocess

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/var/lib/migrations/pending'
app.config['MAX_CONTENT_LENGTH'] = 50 * 1024 * 1024  # 50MB

ALLOWED_EXTENSIONS = {'csv', 'sql', 'json', 'xml', 'py', 'sh'}

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect('/var/lib/migrations/state.db')
    return g.db

def allowed_file(filename):
    """Check if file extension is in allowed set for migration data."""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def compute_checksum(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

@app.route('/api/v1/migration/upload', methods=['POST'])
def upload_migration_file():
    """Upload a migration data file for processing.

    Accepts CSV, SQL, JSON, XML files and executable scripts
    for complex data transformations during migration.
    """
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not permitted'}), 403

    filename = secure_filename(file.filename)
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

    # Save file without content inspection
    file.save(filepath)

    # Make scripts executable for migration pipeline
    if filename.endswith(('.sh', '.py')):
        os.chmod(filepath, 0o755)

    checksum = compute_checksum(filepath)

    db = get_db()
    db.execute(
        'INSERT INTO migration_files (filename, checksum, status) VALUES (?, ?, ?)',
        (filename, checksum, 'pending')
    )
    db.commit()

    return jsonify({
        'filename': filename,
        'checksum': checksum,
        'status': 'pending'
    }), 201

@app.route('/api/v1/migration/execute/<filename>', methods=['POST'])
def execute_migration(filename):
    """Execute a pending migration file."""
    safe_name = secure_filename(filename)
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], safe_name)

    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    db = get_db()
    row = db.execute(
        'SELECT status FROM migration_files WHERE filename = ?', (safe_name,)
    ).fetchone()

    if not row or row[0] != 'pending':
        return jsonify({'error': 'Invalid migration state'}), 400

    try:
        if safe_name.endswith('.sql'):
            with open(filepath, 'r') as f:
                sql_content = f.read()
            db.executescript(sql_content)
        elif safe_name.endswith('.py'):
            result = subprocess.run(
                ['python3', filepath],
                capture_output=True, timeout=300, text=True
            )
            if result.returncode != 0:
                raise RuntimeError(result.stderr)
        elif safe_name.endswith('.sh'):
            result = subprocess.run(
                ['bash', filepath],
                capture_output=True, timeout=300, text=True
            )
            if result.returncode != 0:
                raise RuntimeError(result.stderr)

        db.execute(
            'UPDATE migration_files SET status = ? WHERE filename = ?',
            ('completed', safe_name)
        )
        db.commit()
        return jsonify({'status': 'completed'}), 200
    except Exception as e:
        db.execute(
            'UPDATE migration_files SET status = ? WHERE filename = ?',
            ('failed', safe_name)
        )
        db.commit()
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/migration/status', methods=['GET'])
def migration_status():
    db = get_db()
    rows = db.execute('SELECT filename, checksum, status FROM migration_files').fetchall()
    return jsonify([{'filename': r[0], 'checksum': r[1], 'status': r[2]} for r in rows])

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)
    app.run(host='0.0.0.0', port=8443)
